(x, y, t) => {
  // Gravitational wells - multiple masses creating distortion
  const wells = [
    { x: 160 + Math.sin(t*0.4)*120, y: 80 + Math.cos(t*0.3)*60, m: 2.5 },
    { x: 320 + Math.cos(t*0.5)*100, y: 160 + Math.sin(t*0.6)*80, m: 2.0 },
    { x: 240 + Math.sin(t*0.25+2)*150, y: 120 + Math.cos(t*0.4+1)*100, m: 3.0 },
    { x: 80 + Math.cos(t*0.7+1)*70, y: 200 + Math.sin(t*0.5+3)*50, m: 1.8 },
    { x: 400 + Math.sin(t*0.35+4)*80, y: 40 + Math.cos(t*0.8+2)*60, m: 2.2 },
    { x: 240 + Math.cos(t*0.3+5)*130, y: 220 + Math.sin(t*0.45)*70, m: 1.5 }
  ];

  // Compute gravitational potential and flow at this point
  let potential = 0, kinetic = 0;
  let gx = 0, gy = 0; // gravitational acceleration

  for (const w of wells) {
    const dx = x - w.x, dy = y - w.y;
    const dist2 = dx*dx + dy*dy + 100; // softening
    const dist = Math.sqrt(dist2);
    const force = w.m / dist2;
    potential -= w.m / dist; // gravitational potential
    gx += force * dx / dist; // acceleration components
    gy += force * dy / dist;
  }

  kinetic = Math.sqrt(gx*gx + gy*gy); // kinetic energy proportional to velocity squared

  // Conservation: total energy drives the pattern
  const totalEnergy = potential * 0.3 + kinetic * 15;

  // Organic flow field - follow gravitational streamlines
  const flowMag = Math.sqrt(gx*gx + gy*gy) + 0.001;
  const flowAngle = Math.atan2(gy, gx);

  // Warp coordinates along flow
  const warp = 8;
  const sx = x + Math.cos(flowAngle) * warp * Math.sin(t * 0.5);
  const sy = y + Math.sin(flowAngle) * warp * Math.cos(t * 0.5);

  // Add secondary organic turbulence
  const turb = Math.sin(sx*0.03 + t*0.4) * Math.cos(sy*0.025 - t*0.3) * 12;
  const fx = sx + turb, fy = sy + Math.cos(sx*0.02 - t*0.35) * Math.sin(sy*0.03 + t*0.4) * 10;

  // Reaction-diffusion using multiple sources
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9]
  ];

  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/6, inh = iS/6;

  // Background pattern influenced by energy
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8) + Math.sin(fx*0.03-fy*0.04+t*1.1))/2 
    + Math.sin((fx+fy)*0.12+t*2.5)*0.2 
    + Math.sin((fx-fy)*0.1-t*2)*0.2;

  // Spiral from center influenced by gravity
  const cx = 240, cy = 120;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;

  // Energy-modulated reaction
  const energyMod = Math.tanh(totalEnergy * 0.5);
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + energyMod*0.4)*2.2);

  // Cellular structure
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15) + Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;

  // Potential energy glow (neon highlight on potential wells)
  const potentialGlow = Math.exp(potential * 0.5) * 0.3;

  // Kinetic energy streaks
  const kineticStreak = Math.tanh(kinetic * 8) * 0.2;

  const blend = reaction*0.7 + cell*0.15 + potentialGlow*0.1 + kineticStreak*0.05;
  const v = blend*0.5+0.5;

  // Neon palette - deep blacks to bright neons
  const pal = [
    [2, 2, 8],      // near black with slight blue
    [5, 10, 40],    // deep navy
    [10, 60, 80],   // dark teal
    [0, 180, 160],  // bright cyan
    [180, 255, 220], // neon green-white
    [255, 240, 80],  // neon yellow
    [255, 100, 50],  // neon orange
    [220, 30, 80],   // neon magenta-red
    [120, 10, 60],   // deep magenta
    [40, 5, 30],     // very dark purple
    [2, 2, 8]        // back to black
  ];

  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;

  // High contrast: sharpen the edges
  const sharpness = Math.abs(reaction) > 0.6 ? 1.4 : (Math.abs(reaction) > 0.3 ? 1.15 : 0.85);

  // Neon glow on high energy areas
  const glowBoost = 1.0 + Math.max(0, kineticStreak * 2) + Math.max(0, potentialGlow * 1.5);

  const lum = sharpness * glowBoost;

  return [
    Math.min(255, Math.max(0, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * lum)) | 0,
    Math.min(255, Math.max(0, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * lum)) | 0,
    Math.min(255, Math.max(0, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * lum)) | 0
  ];
}
